import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {onErrorTestSession} from './onErrorTestSession.js';

it('passes an undefined rejection to onError as the cause and rethrows it unchanged', async () => {
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw undefined;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        seen.push(error);
      },
    },
  });

  const rejection = await orchestrator.processMessage(onErrorTestSession).then(
    () => 'resolved',
    reason => reason
  );

  expect({
    rejection,
    calls: seen.length,
    isError: seen[0] instanceof Error,
    hasCause: 'cause' in seen[0],
    cause: seen[0].cause,
  }).toEqual({rejection: undefined, calls: 1, isError: true, hasCause: true, cause: undefined});
});

// specs/hal-engine-config-hooks/spec.md#9
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {onErrorTestSession} from './onErrorTestSession.js';

it('reports a rejection whose string conversion throws and preserves the original reason', async () => {
  const reason = Object.create(null) as {code: number};
  reason.code = 503;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'unused'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      beforeModelResponse: async () => {
        throw reason;
      },
      onError: async (_session, error) => void seen.push(error),
    },
  });

  const rejection = await orchestrator.processMessage(onErrorTestSession).then(
    () => 'resolved',
    thrown => thrown
  );

  expect({
    rejection,
    calls: seen.length,
    isError: seen[0] instanceof Error,
    message: seen[0]?.message,
    cause: seen[0]?.cause,
  }).toEqual({
    rejection: reason,
    calls: 1,
    isError: true,
    message: 'Unknown error',
    cause: reason,
  });
});

